Repair the complete source below. Export exactly `{ sumStride }` with `module.exports`.

`sumStride(values, start, step)` sums the finite numeric elements at indices `start`, `start + step`, and so on while the index remains inside the array. `values` must be an array containing only finite numbers, `start` must be a non-negative integer, and `step` must be a positive integer. A start at or beyond the array length, including an empty array, returns zero. Throw `TypeError` for malformed arguments. Preserve the input array and normal numeric addition order.

Return a corrected complete source file.

```javascript
'use strict';

function sumStride(values, start, step) {
  if (!Array.isArray(values) || !values.every(Number.isFinite) ||
      !Number.isInteger(start) || start < 0 || !Number.isInteger(step) || step <= 0) {
    throw new TypeError('invalid arguments');
  }
  let total = 0;
  for (let index = start; index <= values.length; index += step) {
    total += values[index];
  }
  return total;
}

module.exports = { sumStride };
```

