'use strict';

const assert = require('node:assert');
const api = require('./solution');

assert.deepStrictEqual(Object.keys(api), ['sumStride']);
const { sumStride } = api;

assert.strictEqual(sumStride([], 0, 1), 0);
assert.strictEqual(sumStride([1, 2, 3, 4, 5], 0, 1), 15);
assert.strictEqual(sumStride([1, 2, 3, 4, 5], 0, 2), 9);
assert.strictEqual(sumStride([1, 2, 3, 4, 5], 1, 2), 6);
assert.strictEqual(sumStride([1, 2, 3], 2, 10), 3);
assert.strictEqual(sumStride([1, 2, 3], 3, 1), 0);
assert.strictEqual(sumStride([1, 2, 3], 100, 2), 0);
assert.strictEqual(sumStride([-5, 2.5, 10, -1.5], 1, 2), 1);

const orderSensitive = [1e20, -1e20, 3];
assert.strictEqual(sumStride(orderSensitive, 0, 1), 3);

const values = [4, 5, 6];
const snapshot = values.slice();
sumStride(values, 0, 2);
assert.deepStrictEqual(values, snapshot);

for (const badValues of [null, {}, '123', [1, NaN], [1, Infinity], [1, '2']]) {
  assert.throws(() => sumStride(badValues, 0, 1), TypeError);
}
for (const start of [-1, 0.5, NaN, Infinity, '0']) {
  assert.throws(() => sumStride([1], start, 1), TypeError);
}
for (const step of [0, -1, 1.5, NaN, Infinity, '1']) {
  assert.throws(() => sumStride([1], 0, step), TypeError);
}

